package org.chiangmeng.hadpediatric

import kotlinx.serialization.Serializable

@Serializable
data class PediatricDrug(
    val name: String,
    val tradeName: String? = null,
    val maxConc: Double,
    val concUnit: String? = null,
    val maxConcPeripheral: Double? = null,
    val minDose: Double,
    val maxDose: Double,
    val unit: String,
    val DefaultVolume: Double = 25.0,
    val prescribeUnit: String
)

val PediatricdrugList = PediatricDrugData.PediatricdrugList

data class PediatricCalculationResult(
    val rate: Double = 0.0,
    val displayConc: Double = 0.0,
    val prescribeMg: Double = 0.0,
    val weight: Double = 0.0,
    val dose: Double = 0.0,
    val volumeMl: Double = 25.0,
    val isDoseOver: Boolean = false,
    val isDoseUnder: Boolean = false,
    val isConcOverCentral: Boolean = false,
    val isConcOverPeripheral: Boolean = false,
    val isMinUnit: Boolean = false,
    val prescribeMcgUnitFactor: Double = 1.0,
    val displayPrescribe: Double = 0.0,
    val calculatedConc: Double = 0.0,
    val doseForMaxConc: Double = 0.0,
    val doseForMaxPeripheralConc: Double = 0.0,
    val timeFactor: Double = 1.0,
    val isAllDataPresent: Boolean = false,
    val isConflict: Boolean = false,
    val errorMessage: String = ""
)

object PediatricCalculator {

    fun PediatricCalcPrescribeScreen(
        selectedDrug: PediatricDrug,
        weight: Double,
        doseInput: Double,
        rateHr: Double,
        selectedVolume: Double
    ): PediatricCalculationResult {
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0

        val hoursDouble = if (rateHr > 0) selectedVolume / rateHr else 0.0
        val totalMg = (doseInput * weight * timeFactor * hoursDouble) / 1000.0

        val calculatedConc = if (selectedVolume > 0) totalMg / selectedVolume else 0.0

        val doseForMaxConc =
            if (weight > 0) roundDownWithTol((selectedDrug.maxConc * rateHr * 1000.0) / (weight * timeFactor)) else 0.0
        val maxConcPeripheral = selectedDrug.maxConcPeripheral ?: 0.0
        val doseForMaxPeripheralConc =
            if (weight > 0 && maxConcPeripheral > 0) roundDownWithTol((maxConcPeripheral * rateHr * 1000.0) / (weight * timeFactor)) else 0.0

        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val displayPrescribe = totalMg * prescribeMcgUnitFactor
        val isConcOverPeripheral = compare(calculatedConc, maxConcPeripheral, true, 1)
        val isConcOverCentral = compare(calculatedConc, selectedDrug.maxConc, true, 1)
        val isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true, 1)
        val isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false, 1)

        return PediatricCalculationResult(
            rateHr, calculatedConc, totalMg, weight, doseInput, selectedVolume,
            isDoseOver, isDoseUnder, isConcOverCentral, isConcOverPeripheral,
            isMinUnit, prescribeMcgUnitFactor, displayPrescribe, calculatedConc,
            doseForMaxConc, doseForMaxPeripheralConc, timeFactor,
            isAllDataPresent = weight > 0 && doseInput > 0 && selectedVolume > 0 && rateHr > 0
        )
    }

    fun PediatricCalcDoseScreen(
        selectedDrug: PediatricDrug,
        weight: Double,
        prescribeInput: Double, // 👈 รับค่ายาที่ผสม
        rateHr: Double,
        selectedVolume: Double
    ): PediatricCalculationResult {
        // 1. จัดการแฟกเตอร์หน่วยเวลาและหน่วยยา
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0

        // 2. แปลงยาที่ผสมให้เป็น Base mg
        val totalMg = if (prescribeInput > 0) prescribeInput / prescribeMcgUnitFactor else 0.0

        // 3. 🎯 คำนวณความเข้มข้น (Concentration)
        val calculatedConc = if (selectedVolume > 0) totalMg / selectedVolume else 0.0

        // 4. 🎯 คำนวณหาขนาดยา (Dose) ที่เด็กได้รับ
        val hoursDouble = if (rateHr > 0) selectedVolume / rateHr else 0.0
        val calculatedDose = if (weight > 0 && hoursDouble > 0) {
            (totalMg * 1000.0) / (weight * timeFactor * hoursDouble)
        } else {
            0.0
        }

        // 5. หา Dose สูงสุดที่ยอมรับได้สำหรับ C-line และ P-line
        val doseForMaxConc =
            if (weight > 0) roundDownWithTol((selectedDrug.maxConc * rateHr * 1000.0) / (weight * timeFactor)) else 0.0
        val maxConcPeripheral = selectedDrug.maxConcPeripheral ?: 0.0
        val doseForMaxPeripheralConc = if (weight > 0 && maxConcPeripheral > 0) {
            roundDownWithTol((maxConcPeripheral * rateHr * 1000.0) / (weight * timeFactor))
        } else 0.0

        // 6. เช็ค Over/Under
        val isConcOverPeripheral =
            maxConcPeripheral > 0 && compare(calculatedConc, maxConcPeripheral, true, 1)
        val isConcOverCentral = compare(calculatedConc, selectedDrug.maxConc, true, 1)
        val isDoseOver =
            calculatedDose > 0 && compare(calculatedDose, selectedDrug.maxDose, true, 1)
        val isDoseUnder =
            calculatedDose > 0 && compare(calculatedDose, selectedDrug.minDose, false, 1)

        return PediatricCalculationResult(
            rate = rateHr,
            displayConc = calculatedConc, // หน่วย mg/ml เสมอสำหรับเด็กโต
            prescribeMg = totalMg,
            weight = weight,
            dose = calculatedDose, // 👈 เก็บ Dose ที่คำนวณได้
            volumeMl = selectedVolume,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isConcOverPeripheral = isConcOverPeripheral,
            isMinUnit = isMinUnit,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = prescribeInput,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            doseForMaxPeripheralConc = doseForMaxPeripheralConc,
            timeFactor = timeFactor,
            isAllDataPresent = weight > 0 && prescribeInput > 0 && selectedVolume > 0 && rateHr > 0
        )
    }

    fun PediatricCalcVolumeScreen(
        selectedDrug: PediatricDrug,
        weight: Double,
        doseInput: Double,
        prescribeInput: Double,
        rateHr: Double
    ): PediatricCalculationResult {
        // 1. จัดการแฟกเตอร์ของหน่วย
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0

        // 2. แปลงยาที่ผสมเป็น Base mg
        val prescribeMg = if (prescribeInput > 0) prescribeInput / prescribeMcgUnitFactor else 0.0

        // 3. 🎯 คำนวณปริมาณสารน้ำ (Volume) จาก Dose, Prescribe และ Rate
        val calculatedVolume = if (doseInput > 0 && weight > 0 && timeFactor > 0 && rateHr > 0) {
            // สูตร: Volume = (Prescribe(mg) * 1000 * Rate) / (Dose * Weight * Time)
            (prescribeMg * 1000.0 * rateHr) / (doseInput * weight * timeFactor)
        } else {
            0.0
        }

        // 4. คำนวณความเข้มข้น (Concentration)
        val calculatedConc = if (calculatedVolume > 0) prescribeMg / calculatedVolume else 0.0

        // 5. เช็คความเข้มข้น C-line และ P-line
        val maxConcPeripheral = selectedDrug.maxConcPeripheral ?: 0.0
        val isConcOverPeripheral =
            calculatedVolume > 0 && prescribeInput > 0 && maxConcPeripheral > 0 && compare(
                calculatedConc,
                maxConcPeripheral,
                true,
                1
            )
        val isConcOverCentral = calculatedVolume > 0 && prescribeInput > 0 && compare(
            calculatedConc,
            selectedDrug.maxConc,
            true,
            1
        )

        // 6. เช็ค Dose
        val isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true)
        val isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false)

        val doseForMaxConc = if (weight > 0) {
            roundDownWithTol((selectedDrug.maxConc * rateHr * 1000.0) / (weight * timeFactor))
        } else 0.0

        val doseForMaxPeripheralConc = if (weight > 0 && maxConcPeripheral > 0) {
            roundDownWithTol((maxConcPeripheral * rateHr * 1000.0) / (weight * timeFactor))
        } else 0.0

        return PediatricCalculationResult(
            rate = rateHr,
            displayConc = calculatedConc, // เด็กโตใช้ mg/ml เสมอ
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isConcOverPeripheral = isConcOverPeripheral,
            isMinUnit = isMinUnit,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = prescribeInput,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            doseForMaxPeripheralConc = doseForMaxPeripheralConc,
            timeFactor = timeFactor,
            weight = weight,
            dose = doseInput,
            volumeMl = calculatedVolume, // 👈 ส่ง Volume ที่คำนวณได้กลับไป
            isAllDataPresent = weight > 0 && doseInput > 0 && prescribeInput > 0 && rateHr > 0
        )
    }

    fun smartCalculate(
        fields: Set<CalculatorField>,
        selectedDrug: PediatricDrug,
        weightIn: Double,
        doseInputIn: Double,
        prescribeMgIn: Double,
        volumeMlIn: Double,
        rateIn: Double,
        calculatedConcIn: Double
    ): PediatricCalculationResult {
        val maxConcPeripheral = selectedDrug.maxConcPeripheral ?: 0.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0

        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val prescribeMg = prescribeMgIn / prescribeMcgUnitFactor
        val calculatedConc = if (calculatedConcIn > 0) calculatedConcIn else 0.0
        val rate = if (rateIn > 0) rateIn else 0.0
        val doseInput = if (doseInputIn > 0) doseInputIn else 0.0
        val weight = if (weightIn > 0) weightIn else 0.0
        val volumeMl = if (volumeMlIn > 0) volumeMlIn else 0.0

        val mixingEdits = fields.intersect(
            setOf(
                CalculatorField.PRESCRIBE,
                CalculatorField.VOLUME,
                CalculatorField.CONC
            )
        )
        val infusionEdits = fields.intersect(
            setOf(
                CalculatorField.DOSE,
                CalculatorField.RATE,
                CalculatorField.CONC,
                CalculatorField.WEIGHT
            )
        )

        fun checkError(d: Double, w: Double, c: Double, r: Double, p: Double, v: Double): String {
            val errors = mutableListOf<String>()
            if (d > 0 && w > 0 && c > 0 && r > 0) {
                val expectedR = (d * w * timeFactor) / (c * 1000.0)
                if (compare(expectedR, r, true, 1) || compare(expectedR, r, false, 1)) {
                    errors.add("Rate (IV DIP) ควรจะเป็น ${formatValue(expectedR, 2)} ml/hr")
                }
            }
            if (p > 0 && v > 0 && c > 0) {
                val expectedC = p / v
                if (compare(expectedC, c, true, 1) || compare(expectedC, c, false, 1)) {
                    errors.add("ความเข้มข้น (Conc) ควรจะเป็น ${formatValue(expectedC, 2)}")
                }
            }
            if (d > 0 && w > 0 && r > 0 && p > 0 && v > 0) {
                val expectedR = (d * timeFactor * w * v) / (p * 1000.0)
                if (compare(expectedR, r, true, 1) || compare(expectedR, r, false, 1)) {
                    errors.add("ข้อมูลขัดแย้ง: Rate ควรจะเป็น ${formatValue(expectedR, 2)} ml/hr")
                }
            }
            return errors.joinToString("\n")
        }

        if (fields.size > 4 || mixingEdits.size > 2 || infusionEdits.size > 3) {
            val errorHint =
                checkError(doseInput, weight, calculatedConc, rate, prescribeMg, volumeMl)
            if (errorHint.isNotEmpty()) {
                return PediatricCalculationResult(
                    rate = rate,
                    displayConc = calculatedConc,
                    prescribeMg = prescribeMg,
                    weight = weight,
                    dose = doseInput,
                    volumeMl = volumeMl,
                    isMinUnit = isMinUnit,
                    prescribeMcgUnitFactor = prescribeMcgUnitFactor,
                    displayPrescribe = prescribeMg * prescribeMcgUnitFactor,
                    calculatedConc = calculatedConc,
                    timeFactor = timeFactor,
                    isConflict = true,
                    errorMessage = errorHint,
                    isConcOverPeripheral = calculatedConc > 0 && compare(
                        calculatedConc,
                        maxConcPeripheral,
                        true
                    ),
                    isConcOverCentral = calculatedConc > 0 && compare(
                        calculatedConc,
                        selectedDrug.maxConc,
                        true
                    ),
                    isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true),
                    isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false)
                )
            }
        }

        var p = prescribeMg
        var v = volumeMl
        var c = calculatedConc
        var d = doseInput
        var w = weight
        var r = rate

        repeat(3) {
            if (!fields.contains(CalculatorField.CONC) && v > 0 && p > 0) c = p / v
            if (!fields.contains(CalculatorField.VOLUME) && c > 0 && p > 0) v = p / c
            if (!fields.contains(CalculatorField.PRESCRIBE) && c > 0 && v > 0) p = c * v
            if (!fields.contains(CalculatorField.RATE) && c > 0 && w > 0 && d > 0) r =
                (d * w * timeFactor) / (c * 1000.0)
            if (!fields.contains(CalculatorField.DOSE) && w > 0 && c > 0 && r > 0) d =
                (r * c * 1000.0) / (w * timeFactor)
            if (!fields.contains(CalculatorField.WEIGHT) && d > 0 && c > 0 && r > 0) w =
                (r * c * 1000.0) / (d * timeFactor)
            if (!fields.contains(CalculatorField.CONC) && r > 0 && d > 0 && w > 0 && (p == 0.0 || v == 0.0)) c =
                (d * w * timeFactor) / (r * 1000.0)
        }

        val isAllPresent = d > 0 && p > 0 && v > 0 && c > 0 && r > 0 && w > 0
        return PediatricCalculationResult(
            rate = r, displayConc = c, prescribeMg = p, weight = w, dose = d, volumeMl = v,
            isDoseOver = d > 0 && compare(d, selectedDrug.maxDose, true),
            isDoseUnder = d > 0 && compare(d, selectedDrug.minDose, false),
            isConcOverCentral = c > 0 && compare(c, selectedDrug.maxConc, true),
            isConcOverPeripheral = c > 0 && compare(c, maxConcPeripheral, true),
            isMinUnit = isMinUnit, prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = p * prescribeMcgUnitFactor, calculatedConc = c,
            timeFactor = timeFactor, isAllDataPresent = isAllPresent, isConflict = false
        )
    }
}