package org.chiangmeng.hadpediatric

import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlin.random.Random

class DrugViewModel(val department: Department) : ViewModel() {
    private val repository = DrugRepository()
    
    var weight = mutableStateOf(0.0)
    val activeDrugs = mutableStateListOf<DrugCalculation>()
    
    private val _availableDrugs = MutableStateFlow<List<DrugConfig>>(emptyList())
    val availableDrugs: StateFlow<List<DrugConfig>> = _availableDrugs

    init {
        loadAvailableDrugs()
    }

    private fun loadAvailableDrugs() {
        viewModelScope.launch {
            val drugs = if (department == Department.Newborn) {
                if (!NewbornDrugData.isNewbornLoaded) {
                    NewbornDrugData.init(repository)
                }
                NewbornDrugData.NewborndrugList.map { it.toConfig() }
            } else {
                if (!PediatricDrugData.isLoaded) {
                    PediatricDrugData.init(repository)
                }
                PediatricDrugData.PediatricdrugList.map { it.toConfig() }
            }
            _availableDrugs.value = drugs
        }
    }

    val totalFluidRate: Double
        get() = activeDrugs.sumOf { it.mlPerHour }

    fun addDrug(config: DrugConfig) {
        val newDrug = DrugCalculation(
            id = Random.nextLong().toString(),
            config = config,
            weight = weight.value,
            dose = 0.0,
            volume = 0.0,
            rate = 0.0,
            department = department
        )
        activeDrugs.add(newDrug)
    }

    fun removeDrug(drug: DrugCalculation) {
        activeDrugs.removeAll { it.id == drug.id }
    }

    fun clearAll() {
        activeDrugs.clear()
        weight.value = 0.0
    }

    fun updateWeight(newWeight: Double) {
        weight.value = newWeight
        val updated = activeDrugs.map { it.copy(weight = newWeight) }
        activeDrugs.clear()
        activeDrugs.addAll(updated)
    }

    fun updateDrugCalculation(id: String, dose: Double? = null, volume: Double? = null, rate: Double? = null) {
        val index = activeDrugs.indexOfFirst { it.id == id }
        if (index != -1) {
            val old = activeDrugs[index]
            activeDrugs[index] = old.copy(
                dose = dose ?: old.dose,
                volume = volume ?: old.volume,
                rate = rate ?: old.rate
            )
        }
    }
}
