val PediatricLightBlueColorScheme = lightColorScheme(
    primary = Color(0xFF03A9F4),
    onPrimary = Color.White,
    primaryContainer = Color(0xFFE1F5FE),
    onPrimaryContainer = Color(0xFF01579B),
    secondary = Color(0xFF4FC3F7),
    onSecondary = Color.White,
    background = Color(0xFFF8FDFF),
    surface = Color.White,
    onBackground = Color(0xFF1C1B1F),
    onSurface = Color(0xFF1C1B1F),
    tertiary = Color(0xFF0277BD),
    error = Color(0xFFD32F2F)
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PediatricApp(onBack: () -> Unit, onShowSettings: () -> Unit) {
    var selectedTab by remember { mutableStateOf(0) }
    var selectedDrug by remember { mutableStateOf<PediatricDrug?>(null) }
    val drugViewModel = remember { DrugViewModel(Department.Pediatric) }

    MaterialTheme(
        colorScheme = PediatricLightBlueColorScheme,
        typography = AppSettings.getTypography()
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(selectedDrug, selectedTab) {
                    awaitEachGesture {
                        val down = awaitFirstDown(pass = PointerEventPass.Initial)
                        val startX = down.position.x
                        if (startX < 120f) {
                            var totalDragX = 0f
                            while (true) {
                                val event = awaitPointerEvent(pass = PointerEventPass.Initial)
                                val change = event.changes.firstOrNull() ?: break
                                if (change.pressed) {
                                    val dragAmount = change.positionChange().x
                                    totalDragX += dragAmount
                                    if (totalDragX > 80f) {
                                        change.consume()
                                        if (selectedDrug != null) {
                                            selectedDrug = null
                                        } else if (selectedTab == 5) {
                                            selectedTab = 0
                                        } else {
                                            onBack()
                                        }
                                        break
                                    }
                                } else {
                                    break
                                }
                            }
                        }
                    }
                }
        ) {
            if (selectedDrug == null && selectedTab != 5) {
                DrugSelectionScreen(
                    items = PediatricdrugList,
                    getName = { it.name },
                    getTradeName = { it.tradeName },
                    onItemSelected = { selectedDrug = it },
                    onBack = onBack,
                    title = "Pediatrics Drugs",
                    primaryColor = Color(0xFF03A9F4),
                    headerImage = painterResource(Res.drawable.pediatrictop),
                    backgroundImage = painterResource(Res.drawable.pediatricbg),
                    onShowSettings = onShowSettings,
                    extraContent = {
                        Button(
                            onClick = { selectedTab = 5 },
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF03A9F4))
                        ) {
                            Icon(Icons.Default.LibraryAdd, contentDescription = null)
                            Spacer(Modifier.width(8.dp))
                            Text("Multiple Drugs Infusion", fontWeight = FontWeight.Bold)
                        }
                    }
                )
            } else if (selectedTab == 5) {
                DrugListScreen(
                    viewModel = drugViewModel,
                    onBack = { selectedTab = 0 }
                )
            } else {
                Box(modifier = Modifier.fillMaxSize()) {
                    Image(
                        painter = painterResource(Res.drawable.pediatricbg),
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.FillHeight
                    )
                    Scaffold(
                        containerColor = Color.White.copy(0.5f),
                        topBar = {
                            TopAppBar(
                                title = {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Image(
                                            painter = painterResource(Res.drawable.pediatrictop),
                                            contentDescription = null,
                                            modifier = Modifier.size(80.dp).padding(end = 8.dp),
                                            contentScale = ContentScale.Fit
                                        )
                                        Text(
                                            text = "Pediatrics",
                                            style = MaterialTheme.typography.headlineLarge,
                                            color = Color(0xFF263238),
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                },
                                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.Transparent),
                                navigationIcon = {
                                    IconButton(onClick = { selectedDrug = null }) {
                                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                                    }
                                },
                                actions = {
                                    IconButton(onClick = onShowSettings) {
                                        Icon(Icons.Default.FormatSize, contentDescription = "Font Size", tint = Color.Gray)
                                    }
                                }
                            )
                        },
                        bottomBar = {
                            NavigationBar(
                                containerColor = Color.White,
                                tonalElevation = 8.dp,
                                windowInsets = WindowInsets(0.dp)
                            ) {
                                NavigationBarItem(
                                    selected = selectedTab == 0,
                                    onClick = { selectedTab = 0 },
                                    label = { Text("คำนวณ\nปริมาณยา", textAlign = TextAlign.Center) },
                                    icon = { Icon(Icons.Default.Science, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFFD81B60),
                                        selectedTextColor = Color(0xFFD81B60),
                                        indicatorColor = Color(0xFFF8BBD0),
                                        unselectedIconColor = Color.Gray,
                                        unselectedTextColor = Color.Gray
                                    )
                                )
                                NavigationBarItem(
                                    selected = selectedTab == 1,
                                    onClick = { selectedTab = 1 },
                                    label = { Text("คำนวณ\nDose", textAlign = TextAlign.Center) },
                                    icon = { Icon(Icons.Default.MedicalServices, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFF2E7D32),
                                        selectedTextColor = Color(0xFF2E7D32),
                                        indicatorColor = Color(0xFFC8E6C9),
                                        unselectedIconColor = Color.Gray,
                                        unselectedTextColor = Color.Gray
                                    )
                                )
                                NavigationBarItem(
                                    selected = selectedTab == 2,
                                    onClick = { selectedTab = 2 },
                                    label = { Text("คำนวณ\nVolume", textAlign = TextAlign.Center) },
                                    icon = { Icon(Icons.Default.Opacity, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFF1565C0),
                                        selectedTextColor = Color(0xFF1565C0),
                                        indicatorColor = Color(0xFFBBDEFB),
                                        unselectedIconColor = Color.Gray,
                                        unselectedTextColor = Color.Gray
                                    )
                                )
                                NavigationBarItem(
                                    selected = selectedTab == 3,
                                    onClick = { selectedTab = 3 },
                                    label = { Text("ข้อมูล\nยา", textAlign = TextAlign.Center) },
                                    icon = { Icon(Icons.AutoMirrored.Filled.MenuBook, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFFE65100),
                                        selectedTextColor = Color(0xFFE65100),
                                        indicatorColor = Color(0xFFFFE0B2),
                                        unselectedIconColor = Color.Gray,
                                        unselectedTextColor = Color.Gray
                                    )
                                )
                            }
                        }
                    ) { innerPadding ->
                        Box(modifier = Modifier.padding(innerPadding)) {
                            when (selectedTab) {
                                0 -> PediatricCalcPrescribeScreen(selectedDrug!!)
                                1 -> PediatricCalcDoseScreen(selectedDrug!!)
                                2 -> PediatricCalcVolumeScreen(selectedDrug!!)
                                3 -> PediatricDrugDetailScreen(selectedDrug!!, PediatricdrugList)
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun PediatricDrugLabel(name: String, tradeName: String?) {
    Card(
        modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(2.dp, MaterialTheme.colorScheme.primary)
    ) {
        Text(
            text = "ยา: $name ${if (tradeName != null) "($tradeName)" else ""}",
            modifier = Modifier.padding(16.dp).fillMaxWidth(),
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )
    }
}
