/**
 * คำนวณยาตามอัตราการให้ยา (Rate-based Calculation)
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewbornCalcPrescribeScreen(selectedDrug: NewbornDrug) {
    var selectedRate by remember { mutableStateOf("1") }
    var showDialog by remember { mutableStateOf(false) }
    var showTable by remember { mutableStateOf(false) }
    val focusManager = LocalFocusManager.current
    var weightStr by remember { mutableStateOf(" ") }
    var doseStr by remember { mutableStateOf(" ") }
    var volumeStr by remember { mutableStateOf(selectedDrug.DefaultVolumn.toString()) }
    val weight = weightStr.toDoubleOrNull() ?: 0.0
    val doseInput = doseStr.toDoubleOrNull() ?: 0.0
    val selectedVolume = volumeStr.toDoubleOrNull() ?: 50.0
    val rateHr = selectedRate.toDoubleOrNull()?.let { if (it <= 0.0) 1.0 else it } ?: 1.0

    val result = remember(selectedDrug, weight, doseInput, rateHr, selectedVolume) {
        NewbornCalculator.NewbornCalcPrescribeScreen(
            selectedDrug,
            weight,
            doseInput,
            rateHr,
            selectedVolume
        )
    }

    val textColor = if (!result.isMinUnit) Color.Red else Color.Unspecified
    val textWeight = FontWeight.Bold
    val textDeco = TextDecoration.Underline
    val textSize = 1.1.em

    LaunchedEffect(selectedDrug) {
        weightStr = " "; doseStr = " "; volumeStr =
        " "; selectedRate = " "
    }

    Column(
        modifier = Modifier.padding(4.dp).fillMaxSize()
            .windowInsetsPadding(WindowInsets.systemBars)
            .pointerInput(Unit) { detectTapGestures { focusManager.clearFocus() } }
            .verticalScroll(rememberScrollState())
    ) {
        Text(
            "คำนวณ ปริมาณยา",
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold
        )
        HorizontalDivider()
        Spacer(Modifier.height(8.dp))
        NewbornDrugLabel(selectedDrug.name, selectedDrug.tradeName)
        Spacer(Modifier.height(8.dp))
        OutlinedTextField(
            value = weightStr,
            onValueChange = { weightStr = it },
            label = { Text("น้ำหนัก(kg)") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedContainerColor = Color.White,
                unfocusedContainerColor = Color.White,
                focusedBorderColor = Color(0xFFFDFD96),
                unfocusedBorderColor = Color.Gray
            )
        )
        Spacer(Modifier.height(12.dp))
        OutlinedTextField(
            value = doseStr,
            onValueChange = { doseStr = it },
            label = {
                Text(buildAnnotatedString {
                    append("ขนาดยาที่ต้องการ (")
                    withStyle(
                        SpanStyle(
                            color = textColor,
                            fontWeight = textWeight,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) { append(selectedDrug.unit) }
                    append(")")
                })
            },
            colors = OutlinedTextFieldDefaults.colors(
                unfocusedContainerColor = when {
                    result.isDoseOver -> Color(0xFFFFEBEE); result.isDoseUnder && doseInput > 0 -> Color(
                        0xFFFFF9C4
                    ); else -> Color.White
                },
                focusedContainerColor = when {
                    result.isDoseOver -> Color(0xFFFFEBEE); result.isDoseUnder && doseInput > 0 -> Color(
                        0xFFFFF9C4
                    ); else -> Color.White
                },
                unfocusedBorderColor = when {
                    result.isDoseOver -> Color.Red; result.isDoseUnder && doseInput > 0 -> Color(
                        0xFFFFB300
                    ); else -> MaterialTheme.colorScheme.outline
                },
                focusedBorderColor = when {
                    result.isDoseOver -> Color.Red; result.isDoseUnder && doseInput > 0 -> Color(
                        0xFFFFB300
                    ); else -> MaterialTheme.colorScheme.primary
                }
            ),
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth()
        )
        Text(
            "ขนาดยา ${
                formatValue(
                    result.doseForMaxConc,
                    2
                )
            } (${selectedDrug.unit}) จะให้ความเข้มข้นสูงสุด ${
                formatValue(
                    selectedDrug.maxConc,
                    2
                )
            } ${selectedDrug.concUnit}", color = Color.Blue, style = MaterialTheme.typography.bodySmall
        )
        Spacer(Modifier.height(8.dp))
        if (result.isDoseOver) Text(
            "ขนาดยาเกิน (Max: ${selectedDrug.maxDose})",
            color = Color.Red,
            style = MaterialTheme.typography.bodySmall
        )
        if (result.isDoseUnder) Text(
            "ขนาดยาน้อยกว่าแนะนำ (Min: ${selectedDrug.minDose})",
            color = Color(0xFFFFA500),
            style = MaterialTheme.typography.bodySmall
        )
        Spacer(Modifier.height(8.dp))
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedTextField(
                value = volumeStr,
                onValueChange = { volumeStr = it },
                label = { Text("ปริมาณสารน้ำ (ml)") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedContainerColor = Color.White,
                    unfocusedContainerColor = Color.White,
                    focusedBorderColor = Color(0xFFFDFD96),
                    unfocusedBorderColor = Color.Gray
                ),
                singleLine = true
            )
            Spacer(Modifier.height(8.dp))
            OutlinedTextField(
                value = selectedRate,
                onValueChange = { selectedRate = it },
                label = { Text("Rate (ml/hr)", style = MaterialTheme.typography.bodySmall) },
                modifier = Modifier.weight(1f),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedContainerColor = Color.White,
                    unfocusedContainerColor = Color.White,
                    focusedBorderColor = Color(0xFFFDFD96),
                    unfocusedBorderColor = Color.Gray
                ),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                textStyle = MaterialTheme.typography.bodyMedium,
                singleLine = true
            )
        }
        Spacer(Modifier.height(8.dp))

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Button(
                onClick = { showDialog = true },
                modifier = Modifier.weight(1f),
                enabled = result.isAllDataPresent
            ) { Text("คำนวณผลลัพธ์") }
            OutlinedButton(onClick = { showTable = !showTable }, modifier = Modifier.weight(1f)) {
                Text(text = if (showTable) "ซ่อนตาราง" else "ดูตารางเพิ่มลดยา")
            }
        }

        if (showTable) {
            Spacer(modifier = Modifier.height(16.dp))
            NewbornRateDoseTable(selectedDrug, weight, selectedVolume, result.rate, result.displayPrescribe)
        }
        if (showDialog) {
            AlertDialog(
                onDismissRequest = { showDialog = false },
                title = {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            Icons.Default.Info,
                            null,
                            tint = MaterialTheme.colorScheme.primary
                        ); Spacer(Modifier.width(8.dp)); Text("Order", fontWeight = FontWeight.Bold)
                    }
                },
                text = {
                    Column {
                        Text(buildAnnotatedString {
                            append("ยา ${selectedDrug.name} ($doseInput ")
                            withStyle(
                                SpanStyle(
                                    color = textColor,
                                    fontWeight = textWeight,
                                    textDecoration = textDeco,
                                    fontSize = textSize
                                )
                            ) { append(selectedDrug.unit) }
                            append(")")
                        })
                        Text(
                            buildAnnotatedString {
                                // ท่อนที่ 1: ตัวเลขยาที่ผสม และ หน่วยยา (ทำให้เป็นตัวหนา)
                                withStyle(SpanStyle(fontWeight = FontWeight.Bold)) {
                                    append("${formatValue(result.displayPrescribe, 2)} ${selectedDrug.prescribeUnit}")
                                }

                                // ท่อนที่ 2: ข้อความที่เหลือ (น้ำเกลือ และ Rate) เป็นตัวธรรมดา
                                append(" + D5W up to $selectedVolume ml\nIV drip: ${formatValue(result.rate, 2)} ml/hr")
                            }
                        )
                        HorizontalDivider(Modifier.padding(vertical = 16.dp))
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                Icons.Default.Warning,
                                null,
                                tint = Color.Red
                            ); Spacer(Modifier.width(8.dp));
                            Text(
                                "ควรระวัง",
                                style = MaterialTheme.typography.titleLarge,
                                color = MaterialTheme.colorScheme.error,
                                fontWeight = FontWeight.Bold,
                                modifier = Modifier.padding(top = 8.dp)
                            )
                        }
                        Text(
                            "ความเข้มข้น: ${
                                formatValue(
                                    result.displayConc,
                                    2
                                )
                            } ${selectedDrug.concUnit}"
                        )
                        if (result.isConcOverCentral) {
                            Text(
                                "ความเข้มข้นเกิน! (Max: ${selectedDrug.maxConc} ${selectedDrug.concUnit})",
                                color = Color.Red,
                                fontWeight = FontWeight.Bold
                            )
                        } else if (doseInput > 0) {
                            Text(
                                "ความเข้มข้นเหมาะสม (Max: ${selectedDrug.maxConc} ${selectedDrug.concUnit}",
                                color = Color(0xFF2E7D32)
                            )
                        }

                        Text(text = "ขนาดยา: ${formatValue(result.displayDose, 2)} ${selectedDrug.unit} ")
                        // ตรวจสอบว่ามีข้อมูลเบื้องต้นครบก่อนแสดงสถานะขนาดยา
                        if (doseInput > 0) {
                            val statusMessage = buildAnnotatedString {
                                when {
                                    result.isDoseOver -> {
                                        withStyle(SpanStyle(color = Color.Red, fontWeight = FontWeight.Bold)) {
                                            append("ขนาดยาเกิน! (Max: ${selectedDrug.maxDose}) ")
                                        }
                                    }
                                    result.isDoseUnder -> {
                                        withStyle(SpanStyle(color = Color(0xFFFFA500), fontWeight = FontWeight.Bold)) {
                                            append("ขนาดยาน้อยกว่าแนะนำ (Min: ${selectedDrug.minDose}) ")
                                        }
                                    }
                                    else -> {
                                        withStyle(SpanStyle(color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold)) {
                                            append("ขนาดยาเหมาะสม (${selectedDrug.minDose} - ${selectedDrug.maxDose}) ")
                                        }
                                    }
                                }

                                // ต่อท้ายด้วยหน่วยที่มี Style พิเศษ (ขีดเส้นใต้/สีแดงตามเงื่อนไขเดิม)
                                withStyle(
                                    SpanStyle(
                                        color = textColor,
                                        fontWeight = textWeight,
                                        textDecoration = textDeco,
                                        fontSize = textSize
                                    )
                                ) {
                                    append(selectedDrug.unit)
                                }
                            }

                            Text(
                                text = statusMessage,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp),
                                style = MaterialTheme.typography.bodyMedium,
                                lineHeight = 20.sp // เพิ่มระยะห่างระหว่างบรรทัดให้อ่านง่ายเวลา Font ใหญ่
                            )
                        }
                    }
                },
                confirmButton = { Button(onClick = { showDialog = false }) { Text("ตกลง") } },
                containerColor = MaterialTheme.colorScheme.surface, shape = RoundedCornerShape(8.dp)
            )
        }
    }
}