package org.chiangmeng.hadpediatric

import kotlinx.serialization.Serializable

@Serializable
data class NewbornDrug(
    val name: String,
    val tradeName: String? = null,
    val maxConc: Double,
    val concUnit: String,
    val maxConcPeripheral: Double? = null,
    val minDose: Double,
    val maxDose: Double,
    val unit: String,
    val Multiply: Double,
    val DefaultVolumn: Double,
    val prescribeUnit: String
)

val NewborndrugList = NewbornDrugData.NewborndrugList

data class NewbornCalculationResult(
    val rate: Double = 0.0,
    val displayConc: Double = 0.0,
    val prescribeMg: Double = 0.0,
    val isDoseOver: Boolean = false,
    val isDoseUnder: Boolean = false,
    val isConcOverCentral: Boolean = false,
    val isMcgUnit: Boolean = false,
    val isMinUnit: Boolean = false,
    val prescribeMcgUnitFactor: Double = 1.0,
    val displayPrescribe: Double = 0.0,
    val concUnitFactor: Double = 1.0,
    val calculatedConc: Double = 0.0,
    val doseForMaxConc: Double = 0.0,
    val timeFactor: Double = 1.0,
    val weight: Double = 0.0,
    val dose: Double = 0.0,
    val volumeMl: Double = 0.0,
    val isConcOverPeripheral: Boolean = false,
    val doseForMaxPeripheralConc: Double = 0.0,
    val isAllDataPresent: Boolean = false,
    val isConflict: Boolean = false,
    val errorMessage: String = "",
    val displayDose: Double = 0.0
)

object NewbornCalculator {

    fun NewbornCalcRuleofSixScreen(
        selectedDrug: NewbornDrug,
        weight: Double,
        doseInput: Double,
        volumeMl: Double
    ): NewbornCalculationResult {
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val prescribeMg = selectedDrug.Multiply * weight / prescribeMcgUnitFactor
        val displayPrescribe = prescribeMg * prescribeMcgUnitFactor
        val calculatedConc = if (volumeMl > 0) prescribeMg / volumeMl else 0.0
        val isMcgUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgUnit) 1000.0 else 1.0
        val displayConc = calculatedConc * concUnitFactor
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val doseMgHr = (doseInput * weight * timeFactor) / 1000.0
        val rate = if (calculatedConc > 0) doseMgHr / calculatedConc else 0.0
        val isConcOverCentral = compare(calculatedConc, selectedDrug.maxConc / concUnitFactor, true)
        val isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true)
        val isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false)

        return NewbornCalculationResult(
            rate = rate,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isMinUnit = isMinUnit,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = displayPrescribe,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = 0.0,
            timeFactor = timeFactor,
            dose = doseInput,
            displayDose = doseInput,
            volumeMl = volumeMl,
            weight = weight,
            isAllDataPresent = weight > 0 && doseInput > 0 && volumeMl > 0 && rate > 0
        )
    }

    fun NewbornCalcPrescribeScreen(
        selectedDrug: NewbornDrug,
        weight: Double,
        doseInput: Double,
        rateHr: Double,
        volumeMl: Double
    ): NewbornCalculationResult {
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0
        val hoursDouble = if (rateHr > 0) volumeMl / rateHr else 0.0
        val prescribeMg = (doseInput * weight * timeFactor * hoursDouble) / 1000.0
        val calculatedConc = if (volumeMl > 0) prescribeMg / volumeMl else 0.0
        val displayConc = calculatedConc * concUnitFactor
        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val isConcOverCentral = compare(calculatedConc, maxConcMgMl, true)
        val isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true)
        val isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false)
        val doseForMaxConc = if (weight > 0) roundDownWithTol((selectedDrug.maxConc * rateHr * 1000.0) / (weight * timeFactor) / concUnitFactor) else 0.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val displayPrescribe = prescribeMg * prescribeMcgUnitFactor

        return NewbornCalculationResult(rate = rateHr,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isMinUnit = isMinUnit,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = displayPrescribe,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            timeFactor = timeFactor,
            dose = doseInput,
            displayDose = doseInput,
            volumeMl = volumeMl,
            weight = weight,
            isAllDataPresent = weight > 0 && doseInput > 0 && volumeMl > 0 && rateHr > 0
        )
    }

    fun NewbornCalcDoseScreen(
        selectedDrug: NewbornDrug,
        weight: Double,
        prescribeInput: Double, // ยาที่ผสม
        rateHr: Double,
        volumeMl: Double
    ): NewbornCalculationResult {
        // 1. จัดการแฟกเตอร์หน่วยเวลาและความเข้มข้น
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0

        // 2. แปลงค่ายาที่ผสมให้เป็น Base mg
        val prescribeMg = if (prescribeInput > 0) prescribeInput / prescribeMcgUnitFactor else 0.0

        // 3. คำนวณความเข้มข้น (Concentration)
        val calculatedConc = if (volumeMl > 0) prescribeMg / volumeMl else 0.0
        val displayConc = calculatedConc * concUnitFactor
        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val isConcOverCentral = volumeMl > 0 && prescribeInput > 0 && compare(calculatedConc, maxConcMgMl, true)

        // 4. คำนวณกลับหา Dose (เช่น mcg/kg/min)
        val hoursDouble = if (rateHr > 0) volumeMl / rateHr else 0.0
        val calculatedDose = if (weight > 0 && hoursDouble > 0) {
            (prescribeMg * 1000.0) / (weight * timeFactor * hoursDouble)
        } else {
            0.0
        }

        // 5. เช็ค Dose Over/Under
        val isDoseOver = calculatedDose > 0 && compare(calculatedDose, selectedDrug.maxDose, true)
        val isDoseUnder = calculatedDose > 0 && compare(calculatedDose, selectedDrug.minDose, false)

        // 6. ขนาดยาสูงสุดที่ทำให้ความเข้มข้นไม่เกิน
        val doseForMaxConc = if (weight > 0) {
            roundDownWithTol((selectedDrug.maxConc * rateHr * 1000.0) / (weight * timeFactor) / concUnitFactor)
        } else 0.0

        return NewbornCalculationResult(
            rate = rateHr,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isMcgUnit = selectedDrug.unit.contains("mcg"), // ประยุกต์ใช้แทนได้ถ้ามี
            isMinUnit = isMinUnit,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = prescribeInput,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            timeFactor = timeFactor,
            weight = weight,
            dose = calculatedDose,
            volumeMl = volumeMl,
            displayDose = calculatedDose, // 👈 เก็บค่า Dose ที่คำนวณได้ไว้ตรงนี้
            isAllDataPresent = weight > 0 && prescribeInput > 0 && volumeMl > 0 && rateHr > 0
        )
    }

    fun NewbornCalcVolumeScreen(
        selectedDrug: NewbornDrug,
        weight: Double,
        doseInput: Double,
        prescribeInput: Double,
        rateHr: Double
    ): NewbornCalculationResult {
        // 1. จัดการแฟกเตอร์ของหน่วย
        val isMinUnit = selectedDrug.unit.contains("min")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0

        // 2. แปลงยาที่ผสมเป็น Base mg
        val prescribeMg = if (prescribeInput > 0) prescribeInput / prescribeMcgUnitFactor else 0.0

        // 3. 🎯 หัวใจหลัก: คำนวณปริมาณสารน้ำ (Volume) จาก Dose, Prescribe และ Rate
        val calculatedVolume = if (doseInput > 0 && weight > 0 && timeFactor > 0 && rateHr > 0) {
            // สูตร: Volume = (Prescribe(mg) * 1000 * Rate) / (Dose * Weight * Time)
            (prescribeMg * 1000.0 * rateHr) / (doseInput * weight * timeFactor)
        } else {
            0.0
        }

        // 4. คำนวณความเข้มข้น
        val calculatedConc = if (calculatedVolume > 0) prescribeMg / calculatedVolume else 0.0
        val displayConc = calculatedConc * concUnitFactor
        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val isConcOverCentral = calculatedVolume > 0 && prescribeInput > 0 && compare(calculatedConc, maxConcMgMl, true)

        // 5. เช็ค Dose
        val isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true)
        val isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false)

        val doseForMaxConc = if (weight > 0) {
            roundDownWithTol((selectedDrug.maxConc * rateHr * 1000.0) / (weight * timeFactor) / concUnitFactor)
        } else 0.0

        return NewbornCalculationResult(
            rate = rateHr,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isMinUnit = isMinUnit,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = prescribeInput,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            timeFactor = timeFactor,
            weight = weight,
            dose = doseInput,
            volumeMl = calculatedVolume, // 👈 ส่ง Volume ที่คำนวณได้กลับไป
            displayDose = doseInput,
            isAllDataPresent = weight > 0 && doseInput > 0 && prescribeInput > 0 && rateHr > 0
        )
    }

    fun smartCalculate(
        fields: Set<CalculatorField>,
        selectedDrug: NewbornDrug,
        weightIn: Double,
        doseInputIn: Double,
        prescribeMgIn: Double,
        volumeMlIn: Double,
        rateIn: Double,
        calculatedConcIn: Double
    ): NewbornCalculationResult {
        val maxConcPeripheral = selectedDrug.maxConcPeripheral ?: 0.0
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val isMinUnit = selectedDrug.unit.contains("min")
        val isConcUnit = selectedDrug.concUnit.contains("mcg")
        val timeFactor = if (isMinUnit) 60.0 else 1.0
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val concMcgUnitFactor = if (isConcUnit) 1000.0 else 1.0
        val prescribeMg = prescribeMgIn / prescribeMcgUnitFactor
        val calculatedConc = calculatedConcIn / concMcgUnitFactor
        val rate = if (rateIn > 0) rateIn else 0.0
        val doseInput = if (doseInputIn > 0) doseInputIn else 0.0
        val weight = if (weightIn > 0) weightIn else 0.0
        val volumeMl = if (volumeMlIn > 0) volumeMlIn else 0.0

        val mixingEdits = fields.intersect(setOf(CalculatorField.PRESCRIBE, CalculatorField.VOLUME, CalculatorField.CONC))
        val infusionEdits = fields.intersect(setOf(CalculatorField.DOSE, CalculatorField.RATE, CalculatorField.CONC, CalculatorField.WEIGHT))

        fun checkError(d: Double, w: Double, c: Double, r: Double, p: Double, v: Double): String {
            val errors = mutableListOf<String>()
            if (d > 0 && w > 0 && c > 0 && r > 0) {
                val expectedR = (d * w * timeFactor) / (c * 1000.0)
                if (compare(expectedR, r, true, 2) || compare(expectedR, r, false, 2)) {
                    errors.add("Rate (IV DIP) ควรจะเป็น ${formatValue(expectedR, 2)} ml/hr")
                }
            }
            if (p > 0 && v > 0 && c > 0) {
                val expectedC = p / v
                if (compare(expectedC, c, true, 2) || compare(expectedC, c, false, 2)) {
                    errors.add("ความเข้มข้น (Conc) ควรจะเป็น ${formatValue(expectedC * concMcgUnitFactor, 2)}")
                }
            }
            if (d > 0 && w > 0 && r > 0 && p > 0 && v > 0) {
                val expectedR = (d * timeFactor * w * v) / (p * 1000.0)
                if (compare(expectedR, r, true, 2) || compare(expectedR, r, false, 2)) {
                    errors.add("ข้อมูลขัดแย้ง: Rate ควรจะเป็น ${formatValue(expectedR, 2)} ml/hr")
                }
            }
            return errors.joinToString("\n")
        }

        if (fields.size > 4 || mixingEdits.size > 2 || infusionEdits.size > 3) {
            val errorHint = checkError(doseInput, weight, calculatedConc, rate, prescribeMg, volumeMl)
            if (errorHint.isNotEmpty()) {
                return NewbornCalculationResult(
                    rate = rate, displayConc = calculatedConc * concMcgUnitFactor, prescribeMg = prescribeMg,
                    weight = weight, dose = doseInput, volumeMl = volumeMl, isMinUnit = isMinUnit,
                    prescribeMcgUnitFactor = prescribeMcgUnitFactor, displayPrescribe = prescribeMg * prescribeMcgUnitFactor,
                    calculatedConc = calculatedConc, timeFactor = timeFactor, isConflict = true, errorMessage = errorHint,
                    isConcOverCentral = calculatedConc > 0 &&  compare(calculatedConc, selectedDrug.maxConc, true),
                    isDoseOver = doseInput > 0 && compare(doseInput, selectedDrug.maxDose, true),
                    isDoseUnder = doseInput > 0 && compare(doseInput, selectedDrug.minDose, false)
                )
            }
        }

        var p = prescribeMg
        var v = volumeMl
        var c = calculatedConc
        var d = doseInput
        var w = weight
        var r = rate

        repeat(3) {
            if (!fields.contains(CalculatorField.CONC) && v > 0 && p > 0) c = p / v
            if (!fields.contains(CalculatorField.VOLUME) && c > 0 && p > 0) v = p / c
            if (!fields.contains(CalculatorField.PRESCRIBE) && c > 0 && v > 0) p = c * v
            if (!fields.contains(CalculatorField.RATE) && c > 0 && w > 0 && d > 0) r = (d * w * timeFactor) / (c * 1000.0)
            if (!fields.contains(CalculatorField.DOSE) && w > 0 && c > 0 && r > 0) d = (r * c * 1000.0) / (w * timeFactor)
            if (!fields.contains(CalculatorField.WEIGHT) && d > 0 && c > 0 && r > 0) w = (r * c * 1000.0) / (d * timeFactor)
            if (!fields.contains(CalculatorField.CONC) && r > 0 && d > 0 && w > 0 && (p == 0.0 || v == 0.0)) c = (d * w * timeFactor) / (r * 1000.0)
        }

        val isAllPresent = d > 0 && p > 0 && v > 0 && c > 0 && r > 0 && w > 0
        return NewbornCalculationResult(
            rate = r, displayConc = c * concMcgUnitFactor, prescribeMg = p, weight = w, dose = d, volumeMl = v,
            isDoseOver = d > 0 && compare(d, selectedDrug.maxDose, true),
            isDoseUnder = d > 0 && compare(d, selectedDrug.minDose, false),
            isConcOverCentral = (c * concMcgUnitFactor) > 0 && compare(c * concMcgUnitFactor, selectedDrug.maxConc, true),
            isConcOverPeripheral = (c * concMcgUnitFactor) > 0 && compare(c * concMcgUnitFactor, maxConcPeripheral, true),
            isMinUnit = isMinUnit, prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = p * prescribeMcgUnitFactor, calculatedConc = c, timeFactor = timeFactor,
            isAllDataPresent = isAllPresent, isConflict = false
        )
    }
}
