package org.chiangmeng.hadpediatric

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.firestore.firestore
import kotlinx.coroutines.delay
import kotlinx.coroutines.withTimeoutOrNull

class DrugRepository {
    private val db by lazy { Firebase.firestore }

    suspend fun getAllNewbornDrugs(): List<NewbornDrug> {
        return try {
            println("STEP 1: Fetching NewbornDrugs...")
            // ขยายเวลาเป็น 5 วินาที เพื่อให้ Firebase มีเวลาดึงข้อมูลจาก Server จนเสร็จ
            val snapshot = withTimeoutOrNull(5000L) {
                db.collection("NewbornDrugs").get()
            }
            snapshot?.documents?.mapNotNull { it.data<NewbornDrug>() } ?: emptyList()
        } catch (e: Exception) {
            emptyList()
        }
    }

    suspend fun getAllPediatricDrugs(): List<PediatricDrug> {
        return try {
            println("STEP 1: Fetching PediatricDrugs...")
            val snapshot = withTimeoutOrNull(5000L) {
                db.collection("PediatricDrugs").get()
            }
            snapshot?.documents?.mapNotNull { it.data<PediatricDrug>() } ?: emptyList()
        } catch (e: Exception) {
            emptyList()
        }
    }
}

object NewbornDrugData {
    var NewborndrugList by mutableStateOf<List<NewbornDrug>>(emptyList())
    var isNewbornLoaded by mutableStateOf(false)

    suspend fun init(repository: DrugRepository) {
        if (isNewbornLoaded) return
        var retryCount = 0
        val maxRetries = 5

        // 🔄 วนลูปพยายามโหลดจนกว่าจะได้ข้อมูลจริงๆ
        while (NewborndrugList.isEmpty() && retryCount < maxRetries) {
            val data = repository.getAllNewbornDrugs()

            if (data.isNotEmpty()) {
                // ✅ ได้ข้อมูลแล้ว (จาก Server หรือ Cache)
                NewborndrugList = data
                isNewbornLoaded = true // อนุญาตให้เข้าหน้าแผนกได้
                break // หลุดจากลูป
            }

            // ❌ ถ้ายังไม่ได้ข้อมูล (เน็ตพัง + ไม่มี Cache)
            retryCount++
            delay(2000L)
        }
    }
}

object PediatricDrugData {
    var PediatricdrugList by mutableStateOf<List<PediatricDrug>>(emptyList())
    var isLoaded by mutableStateOf(false)

    suspend fun init(repository: DrugRepository) {
        if (isLoaded) return
        var retryCount = 0
        val maxRetries = 5

        // 🔄 วนลูปพยายามโหลดจนกว่าจะได้ข้อมูลจริงๆ
        while (PediatricdrugList.isEmpty() && retryCount < maxRetries) {
            val data = repository.getAllPediatricDrugs()

            if (data.isNotEmpty()) {
                PediatricdrugList = data
                isLoaded = true // อนุญาตให้เข้าหน้าแผนกได้
                break
            }

            retryCount++
            delay(2000L)
        }
    }
}