@Composable
fun PediatricDrugDetailScreen(selectedDrug: PediatricDrug, allDrugs: List<PediatricDrug>) {
    val listState = rememberLazyListState()
    LaunchedEffect(selectedDrug) {
        val index = allDrugs.indexOf(selectedDrug)
        if (index >= 0) listState.scrollToItem(index)
    }
    Column(modifier = Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.systemBars).background(MaterialTheme.colorScheme.background)) {
        Row(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {
            Text(text = "ข้อมูลอ้างอิง", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)
        }
        HorizontalDivider()
        LazyColumn(state = listState, modifier = Modifier.fillMaxSize(), contentPadding = PaddingValues(12.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            items(allDrugs) { drug ->
                val isSelected = drug == selectedDrug
                PediatricDrugInfoCard(drug = drug, isSelected = isSelected)
            }
            item { Spacer(Modifier.height(100.dp)) }
        }
    }
}

@Composable
fun PediatricDrugInfoCard(drug: PediatricDrug, isSelected: Boolean) {
    val backgroundColor = if (isSelected) Color(0xFFE3F2FD) else Color.White
    val borderColor = if (isSelected) MaterialTheme.colorScheme.primary else Color.Transparent
    val elevation = if (isSelected) 4.dp else 1.dp
    val isMinUnit = drug.unit.contains("min")
    val highlightMode = if (isMinUnit) 1 else 2

    Card(
        modifier = Modifier.fillMaxWidth(),
        colors = CardDefaults.cardColors(containerColor = backgroundColor),
        elevation = CardDefaults.cardElevation(defaultElevation = elevation),
        border = if (isSelected) BorderStroke(2.dp, borderColor) else null
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) {
                Text(
                    text = drug.name,
                    style = MaterialTheme.typography.headlineSmall,
                    color = if (isSelected) MaterialTheme.colorScheme.primary else Color.Black,
                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
                    modifier = Modifier.weight(1f)
                )
                if (isSelected) {
                    Spacer(modifier = Modifier.width(8.dp))
                    Icon(imageVector = Icons.Default.CheckCircle, contentDescription = "Selected", tint = MaterialTheme.colorScheme.primary)
                }
            }
            Text(
                "ชื่อทางการค้า: ${drug.tradeName ?: "N/A"}",
                style = MaterialTheme.typography.bodySmall,
                color = if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.7f) else Color.Gray,
                modifier = Modifier.padding(top = 4.dp)
            )
            HorizontalDivider(modifier = Modifier.padding(vertical = 12.dp), color = if (isSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.2f) else Color.LightGray)
            PediatricDetailRow("ขนาดยาต่ำสุด (Min)", "${drug.minDose}", unit = drug.unit, highlightMode)
            PediatricDetailRow("ขนาดยาสูงสุด (Max)", "${drug.maxDose}", unit = drug.unit, highlightMode)
            PediatricDetailRow(label = if (drug.maxConcPeripheral == null) "ความเข้มข้นสูงสุด (Max)" else "ความเข้มข้น Central line (Max)", "${drug.maxConc}", unit = "mg/ml")
            drug.maxConcPeripheral?.let { maxP -> PediatricDetailRow("ความเข้มข้น Peripheral line (Max)", "$maxP", unit = "mg/ml") }
        }
    }
}

@Composable
fun PediatricDetailRow(label: String, value: String, unit: String, highlightMode: Int = 0) {
    val unitStyle = when (highlightMode) {
        1 -> TextStyle(fontWeight = FontWeight.Bold, textDecoration = TextDecoration.Underline, fontSize = 1.em, color = MaterialTheme.colorScheme.tertiary)
        2 -> TextStyle(fontWeight = FontWeight.Bold, textDecoration = TextDecoration.Underline, fontSize = 1.em, color = Color.Red)
        else -> TextStyle(fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.tertiary, fontSize = 18.sp)
    }
    Row(
        modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.Top
    ) {
        Text(
            text = label,
            modifier = Modifier.weight(1f),
            style = MaterialTheme.typography.bodyMedium
        )
        Spacer(modifier = Modifier.width(12.dp))
        Column(horizontalAlignment = Alignment.End) {
            Text(
                text = value,
                style = MaterialTheme.typography.titleLarge,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.End
            )
            Text(
                text = unit,
                style = unitStyle,
                textAlign = TextAlign.End
            )
        }
    }
}
