package org.chiangmeng.hadpediatric

import androidx.compose.foundation.Image
import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.itemsIndexed
import androidx.compose.foundation.lazy.rememberLazyListState
import androidx.compose.foundation.shape.CircleShape
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.ArrowBack
import androidx.compose.material.icons.filled.FormatSize
import androidx.compose.material.icons.filled.Search
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.draw.rotate
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.painter.Painter
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)
@Composable
fun <T> DrugSelectionScreen(
    items: List<T>,
    getName: (T) -> String,
    getTradeName: (T) -> String? = { null },
    onItemSelected: (T) -> Unit,
    onBack: () -> Unit,
    title: String,
    primaryColor: Color,
    headerImage: Painter? = null,
    backgroundImage: Painter? = null,
    onShowSettings: (() -> Unit)? = null,
    extraContent: @Composable (ColumnScope.() -> Unit)? = null
) {
    var searchQuery by remember { mutableStateOf("") }
    
    val filteredItems = remember(searchQuery, items) {
        items.filter { 
            getName(it).contains(searchQuery, ignoreCase = true) || 
            getTradeName(it)?.contains(searchQuery, ignoreCase = true) == true
        }
            .sortedBy { getName(it).lowercase() }
    }

    val groupedItems = remember(filteredItems) {
        filteredItems.groupBy { getName(it).trim().first().uppercaseChar() }
    }

    val alphabet = ('A'..'Z').toList()
    val availableChars = remember(groupedItems) {
        groupedItems.keys
    }

    val listState = rememberLazyListState()
    val scope = rememberCoroutineScope()

    Box(modifier = Modifier.fillMaxSize()) {
        if (backgroundImage != null) {
            Image(
                painter = backgroundImage,
                contentDescription = null,
                modifier = Modifier.fillMaxSize(),
                contentScale = ContentScale.FillHeight
            )
        }

        Scaffold(
            containerColor = Color.Transparent,
            topBar = {
                TopAppBar(
                    title = {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            if (headerImage != null) {
                                Image(
                                    painter = headerImage,
                                    contentDescription = null,
                                    modifier = Modifier.size(60.dp).padding(end = 8.dp)
                                )
                            }
                            Text(title, style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)
                        }
                    },
                    navigationIcon = {
                        IconButton(onClick = onBack) {
                            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                        }
                    },
                    actions = {
                        if (onShowSettings != null) {
                            IconButton(onClick = onShowSettings) {
                                Icon(Icons.Default.FormatSize, contentDescription = "Font Size", tint = Color.Gray)
                            }
                        }
                    },
                    colors = TopAppBarDefaults.topAppBarColors(
                        containerColor = if (backgroundImage != null) Color.White.copy(alpha = 0.8f) else Color.White,
                        titleContentColor = Color(0xFF263238),
                        navigationIconContentColor = Color(0xFF263238)
                    )
                )
            }
        ) { innerPadding ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(innerPadding)
                    .background(if (backgroundImage == null) Color(0xFFF8F9FA) else Color.Transparent)
            ) {
                extraContent?.invoke(this)

                OutlinedTextField(
                    value = searchQuery,
                    onValueChange = { searchQuery = it },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 8.dp),
                    placeholder = { Text("ค้นหายา...", style = MaterialTheme.typography.bodyMedium) },
                    leadingIcon = { Icon(Icons.Default.Search, contentDescription = null, tint = primaryColor) },
                    shape = RoundedCornerShape(16.dp),
                    singleLine = true,
                    colors = OutlinedTextFieldDefaults.colors(
                        focusedBorderColor = primaryColor,
                        unfocusedBorderColor = Color.LightGray,
                        focusedContainerColor = Color.White,
                        unfocusedContainerColor = Color.White
                    )
                )

                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 4.dp),
                    colors = CardDefaults.cardColors(containerColor = Color.White.copy(alpha = 0.95f)),
                    elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
                    shape = RoundedCornerShape(16.dp)
                ) {
                    FlowRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(8.dp),
                        horizontalArrangement = Arrangement.Center,
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        alphabet.forEach { char ->
                            val isAvailable = availableChars.contains(char)
                            Box(
                                modifier = Modifier
                                    .size(34.dp)
                                    .padding(2.dp)
                                    .clip(CircleShape)
                                    .background(if (isAvailable) primaryColor.copy(alpha = 0.15f) else Color.Transparent)
                                    .clickable(enabled = isAvailable) {
                                        scope.launch {
                                            var targetIndex = 0
                                            val sortedKeys = groupedItems.keys.sorted()
                                            var found = false
                                            for (initial in sortedKeys) {
                                                if (initial == char) {
                                                    found = true
                                                    break
                                                }
                                                targetIndex += 1 // Header
                                                targetIndex += groupedItems[initial]?.size ?: 0 // Items
                                            }
                                            if (found) {
                                                listState.animateScrollToItem(targetIndex)
                                            }
                                        }
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = char.toString(),
                                    style = MaterialTheme.typography.labelMedium,
                                    color = if (isAvailable) primaryColor else Color.LightGray.copy(alpha = 0.5f),
                                    fontWeight = if (isAvailable) FontWeight.Bold else FontWeight.Normal
                                )
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(8.dp))

                LazyColumn(
                    state = listState,
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth(),
                    contentPadding = PaddingValues(bottom = 24.dp)
                ) {
                    val sortedKeys = groupedItems.keys.sorted()
                    sortedKeys.forEach { initial ->
                        val drugs = groupedItems[initial] ?: emptyList()
                        
                        item(key = initial) {
                            Surface(
                                modifier = Modifier.fillMaxWidth(),
                                color = if (backgroundImage != null) Color.Transparent else primaryColor.copy(alpha = 0.05f)
                            ) {
                                Text(
                                    text = initial.toString(),
                                    modifier = Modifier.padding(horizontal = 20.dp, vertical = 6.dp),
                                    style = MaterialTheme.typography.titleMedium,
                                    color = primaryColor,
                                    fontWeight = FontWeight.ExtraBold
                                )
                            }
                        }

                        itemsIndexed(drugs) { index, drug ->
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(Color.White)
                                    .clickable { onItemSelected(drug) }
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 20.dp, vertical = 14.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    val name = getName(drug)
                                    val tradeName = getTradeName(drug)
                                    val displayText = if (tradeName.isNullOrBlank()) name else "$name ($tradeName)"
                                    
                                    Text(
                                        text = displayText,
                                        style = MaterialTheme.typography.bodyLarge,
                                        color = Color.DarkGray,
                                        fontWeight = FontWeight.Medium
                                    )
                                    Icon(
                                        imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                                        contentDescription = null,
                                        modifier = Modifier.size(16.dp).rotate(180f),
                                        tint = Color.LightGray
                                    )
                                }
                                if (index < drugs.size - 1) {
                                    HorizontalDivider(
                                        modifier = Modifier.padding(horizontal = 20.dp),
                                        thickness = 0.5.dp,
                                        color = Color(0xFFEEEEEE)
                                    )
                                }
                            }
                        }
                    }
                    
                    if (filteredItems.isEmpty()) {
                        item {
                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(top = 64.dp)
                                    .background(if (backgroundImage != null) Color.White.copy(alpha = 0.7f) else Color.Transparent),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    "ไม่พบรายชื่อยาที่ค้นหา",
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = Color.Gray
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}
