/**
 * กำหนดสีของ TextField ในโหมด Smart Calculate
 */
@Composable
fun getNewbornSmartColors(isCalculating: Boolean, editedFields: Set<CalculatorField>, field: CalculatorField, activeContainerColor: Color = Color.White, activeUnfocusedBorder: Color = Color.Gray, activeFocusedBorder: Color = Color(0xFFFDFD96)): TextFieldColors {
    return OutlinedTextFieldDefaults.colors(
        focusedContainerColor = if (isCalculating && editedFields.contains(field)) Color.White else activeContainerColor,
        unfocusedContainerColor = if (isCalculating && editedFields.contains(field)) Color.White else activeContainerColor,
        focusedBorderColor = if (isCalculating && editedFields.contains(field)) Color.Blue else activeFocusedBorder,
        unfocusedBorderColor = if (isCalculating && editedFields.contains(field)) Color.Blue else activeUnfocusedBorder
    )
}
