package org.chiangmeng.hadpediatric

import androidx.compose.foundation.gestures.detectTapGestures
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Info
import androidx.compose.material.icons.filled.Warning
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.input.pointer.pointerInput
import androidx.compose.ui.platform.LocalFocusManager
import androidx.compose.ui.text.SpanStyle
import androidx.compose.ui.text.buildAnnotatedString
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.style.TextDecoration
import androidx.compose.ui.text.withStyle
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.em
import androidx.compose.ui.unit.sp

/**
 * คำนวณยาแบบกำหนดขนาดยาคงที่ (Fixed Prescribe)
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewbornCalcRuleofSixScreen(selectedDrug: NewbornDrug) {
    val focusManager = LocalFocusManager.current
    var showDialog by remember { mutableStateOf(false) }
    var showTable by remember { mutableStateOf(false) }
    var weightStr by remember { mutableStateOf(" ") }
    var doseStr by remember { mutableStateOf(" ") }
    var volumeMlStr by remember { mutableStateOf(selectedDrug.DefaultVolumn.toString()) }
    val weight = weightStr.toDoubleOrNull() ?: 0.0
    val doseInput = doseStr.toDoubleOrNull() ?: 0.0
    val volumeMl = volumeMlStr.toDoubleOrNull() ?: 0.0

    val result = remember(selectedDrug, weight, doseInput, volumeMl) {
        NewbornCalculator.NewbornCalcRuleofSixScreen(selectedDrug, weight, doseInput, volumeMl)
    }

    val dosePer1Ml = remember(selectedDrug, volumeMl) {
        if (volumeMl > 0 && selectedDrug.Multiply > 0) {
            // โยนน้ำหนักหลอกๆ เป็น 1.0 เพราะใน Rule of Six น้ำหนักจะตัดกันทิ้งไปเอง
            val dummyResult = NewbornCalculator.NewbornCalcRuleofSixScreen(selectedDrug, 1.0, 1.0, volumeMl)
            if (dummyResult.rate > 0) 1.0 / dummyResult.rate else 0.0
        } else {
            0.0
        }
    }

    LaunchedEffect(selectedDrug) {
        weightStr = " "; doseStr = " "; volumeMlStr = selectedDrug.DefaultVolumn.toString()
        showTable = false
    }

    Column(
        modifier = Modifier.padding(4.dp).fillMaxSize()
            .windowInsetsPadding(WindowInsets.systemBars)
            .pointerInput(Unit) { detectTapGestures(onTap = { focusManager.clearFocus() }) }
            .verticalScroll(rememberScrollState())
    ) {
        Text(text = "คำนวณยาตาม Rule-of-Six", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold)
        HorizontalDivider()
        Spacer(modifier = Modifier.height(8.dp))
        NewbornDrugLabel(selectedDrug.name, selectedDrug.tradeName)
        Spacer(modifier = Modifier.height(8.dp))
        OutlinedTextField(
            value = weightStr, onValueChange = { weightStr = it }, label = { Text("น้ำหนัก(kg)") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal), modifier = Modifier.fillMaxWidth(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedContainerColor = Color.White,
                unfocusedContainerColor = Color.White,
            )
        )
        Spacer(modifier = Modifier.height(8.dp))
        OutlinedTextField(
            value = doseStr, onValueChange = { doseStr = it }, label = { Text("ขนาดยา (${selectedDrug.unit})") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal), modifier = Modifier.fillMaxWidth(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedContainerColor = Color.White,
                unfocusedContainerColor = Color.White,
            )
        )
        Spacer(Modifier.height(8.dp))
        if (result.isDoseOver) Text(
            "ขนาดยาเกิน (Max: ${selectedDrug.maxDose})",
            color = Color.Red,
            style = MaterialTheme.typography.bodySmall
        )
        if (result.isDoseUnder) Text(
            "ขนาดยาน้อยกว่าแนะนำ (Min: ${selectedDrug.minDose})",
            color = Color(0xFFFFA500),
            style = MaterialTheme.typography.bodySmall
        )
        Spacer(modifier = Modifier.height(8.dp))
        OutlinedTextField(
            value = volumeMlStr, onValueChange = { volumeMlStr = it }, label = { Text("ปริมาณสารน้ำ (ml)") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal), modifier = Modifier.fillMaxWidth(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedContainerColor = Color.White,
                unfocusedContainerColor = Color.White,
            )
        )
        if (dosePer1Ml > 0) {
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = "💡 Rate 1 ml/hr = ${formatValue(dosePer1Ml, 2)} ${selectedDrug.unit}",
                color = MaterialTheme.colorScheme.primary,
                style = MaterialTheme.typography.bodyMedium,
                fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(start = 4.dp)
            )
        }
        Spacer(modifier = Modifier.height(8.dp))
        
        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = { showDialog = true }, modifier = Modifier.weight(1f), enabled = selectedDrug.Multiply > 0 && result.isAllDataPresent) {
                Text(text = "คำนวณผลลัพธ์") 
            }
            OutlinedButton(onClick = { showTable = !showTable }, modifier = Modifier.weight(1f), enabled = selectedDrug.Multiply > 0) {
                Text(text = if (showTable) "ซ่อนตาราง" else "ดูตารางเพิ่มลดยา")
            }
        }
        if( selectedDrug.Multiply == 0.0){
        Text(
            "ข้อมูลยังไ่ม่พร้อมสำหรับยา ${selectedDrug.name}(${selectedDrug.tradeName})",
            color = Color.Red,
            style = MaterialTheme.typography.bodySmall
        )}

        if (showTable) {
            Spacer(modifier = Modifier.height(16.dp))
            NewbornRateDoseTable(selectedDrug, weight, volumeMl, result.rate, weight * selectedDrug.Multiply)
        }

        if (showDialog) {
            val textColor = if (!result.isMinUnit) Color.Red else Color.Unspecified
            val textWeight = FontWeight.Bold
            val textDeco = TextDecoration.Underline
            val textSize = 1.1.em

            AlertDialog(
                onDismissRequest = { showDialog = false },
                title = { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Info, null, tint = MaterialTheme.colorScheme.primary); Spacer(Modifier.width(8.dp)); Text("Order", fontWeight = FontWeight.Bold) } },
                text = {
                    Column {
                        Text(buildAnnotatedString {
                            append("ยา ${selectedDrug.name} ($doseInput ")
                            withStyle(SpanStyle(color = textColor, fontWeight = textWeight, textDecoration = textDeco, fontSize = textSize)) { append(selectedDrug.unit) }
                            append(")")
                        })
                        Text(text = "${formatValue(result.displayPrescribe, 2)} ${selectedDrug.prescribeUnit} + D5W up to $volumeMl ml\nIV drip: ${
                            formatValue(
                                result.rate,
                                2
                            )
                        } ml/hr")
                        HorizontalDivider(modifier = Modifier.padding(vertical = 16.dp))
                        Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Warning, null, tint = Color.Red); Spacer(Modifier.width(8.dp)); Text("ควรระวัง", style = MaterialTheme.typography.titleLarge, color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 8.dp)) }
                        Text(text = "ความเข้มข้น: ${formatValue(result.displayConc, 2)} ${selectedDrug.concUnit} ")
                        if (result.isConcOverCentral) {
                            Text(text = "ความเข้มข้นเกิน! (Max: ${selectedDrug.maxConc} ${selectedDrug.concUnit} )", color = Color.Red, fontWeight = FontWeight.Bold)
                        } else if (doseInput > 0) {
                            Text(text = "ความเข้มข้นเหมาะสม (Max: ${selectedDrug.maxConc} ${selectedDrug.concUnit})", color = Color(0xFF2E7D32))
                        }
                        Text(text = "ขนาดยา: ${formatValue(result.displayDose, 2)} ${selectedDrug.unit} ")
                        // ตรวจสอบว่ามีข้อมูลเบื้องต้นครบก่อนแสดงสถานะขนาดยา
                        if (doseInput > 0) {
                            val statusMessage = buildAnnotatedString {
                                when {
                                    result.isDoseOver -> {
                                        withStyle(SpanStyle(color = Color.Red, fontWeight = FontWeight.Bold)) {
                                            append("ขนาดยาเกิน! (Max: ${selectedDrug.maxDose}) ")
                                        }
                                    }
                                    result.isDoseUnder -> {
                                        withStyle(SpanStyle(color = Color(0xFFFFA500), fontWeight = FontWeight.Bold)) {
                                            append("ขนาดยาน้อยกว่าแนะนำ (Min: ${selectedDrug.minDose}) ")
                                        }
                                    }
                                    else -> {
                                        withStyle(SpanStyle(color = Color(0xFF2E7D32), fontWeight = FontWeight.Bold)) {
                                            append("ขนาดยาเหมาะสม (${selectedDrug.minDose} - ${selectedDrug.maxDose}) ")
                                        }
                                    }
                                }

                                // ต่อท้ายด้วยหน่วยที่มี Style พิเศษ (ขีดเส้นใต้/สีแดงตามเงื่อนไขเดิม)
                                withStyle(
                                    SpanStyle(
                                        color = textColor,
                                        fontWeight = textWeight,
                                        textDecoration = textDeco,
                                        fontSize = textSize
                                    )
                                ) {
                                    append(selectedDrug.unit)
                                }
                            }

                            Text(
                                text = statusMessage,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp),
                                style = MaterialTheme.typography.bodyMedium,
                                lineHeight = 20.sp // เพิ่มระยะห่างระหว่างบรรทัดให้อ่านง่ายเวลา Font ใหญ่
                            )
                        }
                    }
                },
                confirmButton = { Button(onClick = { showDialog = false }) { Text("ตกลง") } },
                containerColor = Color.White, shape = RoundedCornerShape(8.dp)
            )
        }
    }
}
