fun formatValue(value: Double, digits: Int): String {
    if (value <= 0.0) return "0." + "0".repeat(digits)
    
    var actualDigits = digits
    if (value < 1 && value > 0.0) actualDigits = maxOf(digits, 3)
    if (value < 0.1 && value > 0.0) actualDigits = maxOf(digits, 4)
    if (value < 0.01 && value > 0.0) actualDigits = maxOf(digits, 5)
    if (value < 0.001 && value > 0.0) actualDigits = maxOf(digits, 6)
    
    val factor = 10.0.pow(actualDigits)
    val roundedValue = kotlin.math.round(value * factor) / factor
    val formatted = roundedValue.toString()
    
    return if (!formatted.contains(".")) {
        "$formatted." + "0".repeat(actualDigits)
    } else {
        val parts = formatted.split(".")
        val decimalPart = parts[1].padEnd(actualDigits, '0')
        "${parts[0]}.$decimalPart"
    }
}

fun Double.formatNoDotZero(): String {
    return if (this == this.toLong().toDouble()) {
        this.toLong().toString()
    } else {
        ((this * 100).roundToInt() / 100.0).toString()
    }
}

fun compare(data: Double, test: Double, more: Boolean, level: Int = 0): Boolean {
    val baseTol = when {
        data < 0.0001 -> 0.0000001
        data < 0.001 -> 0.000001
        data < 0.01 -> 0.00001
        data < 0.1 -> 0.0001
        data < 1.0 -> 0.001
        else -> 0.01
    }
    var multiplier = 1.0
    repeat(level) { multiplier *= 10.0 }
    val tol = baseTol * multiplier
    val diff = if (more) data - test else test - data
    return diff > tol
}

fun roundDownWithTol(data: Double): Double {
    val tol = when {
        data < 0.0001 -> 0.0000001
        data < 0.001 -> 0.000001
        data < 0.01 -> 0.00001
        data < 0.1 -> 0.0001
        data < 1.0 -> 0.001
        else -> 0.01
    }
    val factor = 1.0 / tol
    return floor(data * factor) / factor
}

@Composable
fun getSmartColors(
    isCalculating: Boolean,
    editedFields: Set<CalculatorField>,
    targetField: CalculatorField,
    activeContainerColor: Color = Color.White,
    activeUnfocusedBorder: Color = Color.Gray,
    activeFocusedBorder: Color = Color(0xFFFDFD96)
): TextFieldColors {
    val isStale = isCalculating && !editedFields.contains(targetField)

    return OutlinedTextFieldDefaults.colors(
        focusedTextColor = if (isStale) Color.LightGray else Color.Black,
        unfocusedTextColor = if (isStale) Color.LightGray else Color.Black,
        focusedContainerColor = if (isStale) Color.White else activeContainerColor,
        unfocusedContainerColor = if (isStale) Color.White else activeContainerColor,
        focusedBorderColor = if (isStale) Color.LightGray else activeFocusedBorder,
        unfocusedBorderColor = if (isStale) Color.LightGray else activeUnfocusedBorder,
        disabledContainerColor = Color.White
    )
}

